{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin absolute bioavailability was 91.2% in healthy subjects after oral tablets compared with intravenous injection, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Amoxicillin absolute bioavailability was 88.7% (range 70.9–105.5%) in normal men after a 250-mg oral capsule compared with IV, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Pentazocine absolute bioavailability was 18% in healthy subjects after oral solution compared with IV, below the 20% threshold; this is the main contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer evidence molecules show absolute oral bioavailability clearly above 20% in healthy subjects, including digitoxin 91%, amoxicillin 89%, UDCA 50%, and DHA 45–77%. The single contradictory pentazocine record (18%) is below threshold but is variable and condition-dependent, so F >= 20% is better supported overall.",
  "evidence_gaps": [
    "The contradictory pentazocine evidence is close to the threshold and shows wide inter-individual variability, with individual tablet values from about 11% to 32% and a much higher value in cirrhosis.",
    "The evidence set contains only one molecule with a healthy-subject F below 20%, limiting direct negative support."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

